# Gallery references can be shortlisted without confusing mixed photographs with a real wedding story.
p=ROOT/'work.html';s=p.read_text()
if 'data-inspiration=' not in s:
 def gallery_ref(m):
  b=m.group();name=re.search(r'data-photo="([^"]+)"',b).group(1);alt=re.search(r'alt="([^"]*)"',b).group(1)
  return '<div class="gallery-item">'+b+f'<button type="button" class="save-look" data-inspiration="{name}" data-inspiration-label="{alt}" aria-pressed="false">Save this look</button></div>'
 s=re.sub(r'<button[^>]*class="photo"[^>]*>.*?</button>',gallery_ref,s)
 s=s.replace('<section class="wrap portfolio">','<section class="wrap portfolio"><div class="saved-look-intro"><p>Save a few looks to discuss in your enquiry. A reference helps explain your preferences.</p><a href="./plan.html#shortlist" class="text-link dark" data-shortlist-link>Your saved looks</a></div><p class="save-feedback" aria-live="polite" id="save-look-feedback"></p>')
p.write_text(s)

